/**
 * @vitest-environment jsdom
 */
import { compileScript, parse } from '@vue/compiler-sfc'
import * as Vue from 'vue'
import * as ssr from '@vue/server-renderer'

function compile(src: string, id: string, isSSR: boolean) {
  const { descriptor } = parse(src, { filename: id + '.vue' })
  const res = compileScript(descriptor, {
    id,
    inlineTemplate: true,
    templateOptions: { ssr: isSSR, ssrCssVars: descriptor.cssVars } as any,
  })
  let code = res.content
    .replace(/import \{([^}]*)\} from "vue\/server-renderer"/g, 'const {$1} = SSR')
    .replace(/import \{([^}]*)\} from ["']vue["']/g, (_, s) => `const {${s.replace(/ as /g, ': ')}} = Vue`)
    .replace(/import ComponentTest from '.\/ComponentTest.vue'/, '')
    .replace('export default', 'return')
  return new Function('Vue', 'SSR', 'ComponentTest', code)
}

const appSrc = `<script setup>
import ComponentTest from './ComponentTest.vue'
const props = defineProps({
  backgroundColor: { type: String, default: 'blue' },
  padding: { type: String, default: '20px' }
})
</script>
<template>
  <ComponentTest class="parent-component">
    <div class="child-content">Hello</div>
  </ComponentTest>
</template>
<style scoped>
.parent-component { background-color: v-bind('props.backgroundColor') }
.child-content { color: #fff; padding: v-bind('props.padding') }
</style>`
const childSrc = `<template>
  <div :style="{ display }"><slot name="default" /></div>
</template>
<script setup>
defineProps({ display: { type: String, default: 'flex' } })
</script>`

test('repro', async () => {
  const ChildS = compile(childSrc, 'c', true)(Vue, ssr)
  const AppS = compile(appSrc, 'a', true)(Vue, ssr, ChildS)
  const ChildC = compile(childSrc, 'c', false)(Vue, ssr)
  const AppC = compile(appSrc, 'a', false)(Vue, ssr, ChildC)
  const html = await ssr.renderToString(Vue.createSSRApp(AppS))
  console.log(html)
  const container = document.createElement('div')
  container.innerHTML = html
  Vue.createSSRApp(AppC).mount(container)
})

